 'use strict';
let analyticsDays=7,analyticsScope='current';
const analyticsDay=t=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t));
function loyaltyAnalytics(shops,days=7,time=Date.now()){
 const buckets=Array.from({length:days},(_,i)=>({key:analyticsDay(time-(days-1-i)*86400000),time:time-(days-1-i)*86400000,visits:0,rewards:0,customers:0}));const map=new Map(buckets.map(b=>[b.key,b]));let members=0,available=0;
 for(const s of shops){members+=s.members.length;available+=s.members.reduce((n,m)=>n+Loyalty.available(m,s.card),0);for(const m of s.members){const b=map.get(analyticsDay(m.joined||0));if(b)b.customers++;}for(const l of s.logs){if(l.undone||!['stamp','redeem'].includes(l.type))continue;const b=map.get(analyticsDay(l.time));if(b)b[l.type==='stamp'?'visits':'rewards']++;}}
 const total=key=>buckets.reduce((n,b)=>n+b[key],0),today=buckets.at(-1),yesterday=buckets.at(-2);return {buckets,members,available,today,totals:{visits:total('visits'),rewards:total('rewards'),customers:total('customers')},change:today.visits-(yesterday?.visits||0)};
}
function analyticsBar(data,key,label,color){const max=Math.max(1,...data.buckets.map(b=>b[key])),w=680,h=210,pad=28,step=(w-pad*2)/data.buckets.length,bw=Math.min(34,step*.65);return `<div class="analytics-chart"><svg viewBox="0 0 ${w} ${h+35}" role="img" aria-label="${label}" style="--chart-color:${color}">${[0,1,2,3].map(i=>{const y=20+i*(h-35)/3;return `<line x1="${pad}" y1="${y}" x2="${w-pad}" y2="${y}" stroke="#e5ece8" stroke-dasharray="3 4"/><text x="6" y="${y+4}" fill="#82948b" font-size="10">${fmt(Math.round(max*(3-i)/3))}</text>`;}).join('')}${data.buckets.map((b,i)=>{const bh=b[key]/max*(h-35),x=pad+i*step+(step-bw)/2,y=h-15-bh,date=new Date(b.time).toLocaleDateString('ar-SA',{day:'numeric',month:'short',timeZone:'Asia/Riyadh'});return `<g tabindex="0"><title>${date}: ${fmt(b[key])} ${label}</title><rect x="${x}" y="${y}" width="${bw}" height="${Math.max(bh,2)}" rx="5" fill="var(--chart-color)" opacity="${b[key]?1:.18}"/>${data.buckets.length<=7||i%5===0?`<text x="${x+bw/2}" y="${h+15}" text-anchor="middle" fill="#73877d" font-size="10">${date}</text>`:''}</g>`;}).join('')}</svg></div>`;}
const analyticsOwner=ownerHTML;
ownerHTML=function(){if(view!=='overview')return analyticsOwner();const all=db.shops.filter(s=>!s.archivedAt),selected=analyticsScope==='all'?all:[shop()],a=loyaltyAnalytics(selected,analyticsDays),name=analyticsScope==='all'?'جميع برامج النشاط':shop().card.title||shop().name;const metric=(label,value,detail,i)=>`<article class="analytics-metric"><span>${label} ${icon(i)}</span><b>${fmt(value)}</b><small>${detail}</small></article>`;
 return head('أداء برامج الولاء','نظرة عامة',esc(name),`<button class="btn primary" data-action="nav" data-view="join">${icon('link')} رابط التسجيل</button>`)+`<div class="analytics-toolbar"><label>البيانات <select data-analytics="scope" aria-label="نطاق الإحصاءات"><option value="current" ${analyticsScope==='current'?'selected':''}>البطاقة الحالية</option><option value="all" ${analyticsScope==='all'?'selected':''}>جميع بطاقات النشاط</option></select></label><label>الفترة <select data-analytics="days" aria-label="فترة الإحصاءات"><option value="7" ${analyticsDays===7?'selected':''}>آخر ٧ أيام</option><option value="30" ${analyticsDays===30?'selected':''}>آخر ٣٠ يومًا</option></select></label><small>التوقيت: الرياض · العمليات المتراجع عنها مستبعدة</small></div><div class="analytics-metrics">${metric('عملاء البرنامج',a.members,'عدد عضويات العملاء في البطاقات المختارة','users')}${metric('زيارات اليوم',a.today.visits,`${a.change>0?'زيادة':a.change<0?'انخفاض':'دون تغير'} ${fmt(Math.abs(a.change))} مقارنة بأمس`,'coffee')}${metric('مكافآت جاهزة',a.available,'متاحة للعملاء ولم تُصرف بعد','gift')}${metric('مكافآت مصروفة',a.totals.rewards,`خلال آخر ${fmt(analyticsDays)} أيام`,'check')}</div><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>حركة الزيارات</h2><p>الزيارات المؤهلة يومًا بيوم · تشمل إضافة النقاط</p></div><b>${fmt(a.totals.visits)} زيارة</b></div>${analyticsBar(a,'visits','زيارات','#315c49')}</section><section class="panel"><div class="panel-head"><div><h2>المكافآت المصروفة</h2><p>المكافآت التي سلّمها فريقك فعليًا</p></div><b>${fmt(a.totals.rewards)} مكافأة</b></div>${analyticsBar(a,'rewards','مكافآت مصروفة','#92ad54')}</section><section class="panel"><div class="panel-head"><div><h2>العملاء الجدد</h2><p>عضويات انضمت للبرنامج خلال الفترة</p></div><b>${fmt(a.totals.customers)} عميل</b></div>${analyticsBar(a,'customers','عملاء جدد','#708f81')}</section><section class="panel"><div class="panel-head"><div><h2>آخر العمليات</h2><p>زيارات ومكافآت من البطاقات المختارة</p></div><button class="btn quiet small" data-action="nav" data-view="activity">سجل البطاقة</button></div>${logsHTML(selected.flatMap(s=>s.logs.filter(l=>!l.undone).map(l=>({...l,shopName:s.card.title||s.name}))).sort((a,b)=>b.time-a.time),5)}</section></div>`;};
document.addEventListener('change',e=>{if(!e.target.matches('[data-analytics]'))return;if(e.target.dataset.analytics==='days')analyticsDays=Number(e.target.value);else analyticsScope=e.target.value;render();});
render();
